import React, { useState } from 'react';

const CURRENCIES = ['DKK', 'EUR', 'USD', 'GBP', 'SEK', 'NOK'];
const THEMES = [
  { id: 'warm', label: 'Warm Sand', bg: '#F5F0EB', accent: '#A0856C' },
  { id: 'cool', label: 'Cool Mist', bg: '#EEF0F2', accent: '#7A8FA6' },
  { id: 'sage', label: 'Sage', bg: '#EEF2EE', accent: '#7A9E87' },
  { id: 'dark', label: 'Midnight', bg: '#1C1C1E', accent: '#A0856C' },
];
const WEEK_STARTS = ['Monday', 'Sunday'];

function Settings({ settings, setSettings }) {
  const [saved, setSaved] = useState(false);
  const [form, setForm] = useState(settings);
  const [showClearConfirm, setShowClearConfirm] = useState(false);
  const [clearConfirmText, setClearConfirmText] = useState('');

  function saveSettings() {
    setSettings(form);
    // Apply theme
    const theme = THEMES.find(t => t.id === form.theme);
    if (theme) {
      document.documentElement.style.setProperty('--bg', theme.bg);
      document.documentElement.style.setProperty('--accent', theme.accent);
    }
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  }

  function clearAllData() {
    localStorage.clear();
    setShowClearConfirm(false);
    window.location.reload();
  }

  return (
    <div style={{ padding: '32px 24px 40px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em' }}>PREFERENCES</p>
      <h1 style={{ fontSize: '28px', fontWeight: '300', marginTop: '4px', marginBottom: '28px' }}>Settings</h1>

      {/* Profile */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '16px' }}>
        <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '14px' }}>PROFILE</p>
        <label style={labelStyle}>YOUR NAME</label>
        <input
          value={form.name}
          onChange={e => setForm({ ...form, name: e.target.value })}
          placeholder="Your name"
          style={inputStyle}
        />
      </div>

      {/* Appearance */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '16px' }}>
        <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '14px' }}>APPEARANCE</p>
        <label style={labelStyle}>THEME</label>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginBottom: '20px' }}>
          {THEMES.map(theme => (
            <button key={theme.id} onClick={() => setForm({ ...form, theme: theme.id })} style={{
              padding: '14px', borderRadius: '12px', border: '2px solid',
              borderColor: form.theme === theme.id ? 'var(--accent)' : 'var(--border)',
              backgroundColor: theme.bg, cursor: 'pointer',
              display: 'flex', alignItems: 'center', gap: '8px',
            }}>
              <div style={{ width: '16px', height: '16px', borderRadius: '50%', backgroundColor: theme.accent, flexShrink: 0 }} />
              <span style={{ fontSize: '12px', fontFamily: 'Jost, sans-serif', color: theme.id === 'dark' ? '#fff' : '#2C2C2C' }}>{theme.label}</span>
            </button>
          ))}
        </div>

        <label style={labelStyle}>WEEK STARTS ON</label>
        <div style={{ display: 'flex', gap: '8px', marginBottom: '4px' }}>
          {WEEK_STARTS.map(day => (
            <button key={day} onClick={() => setForm({ ...form, weekStartsOn: day })} style={{
              flex: 1, padding: '10px', borderRadius: '10px', border: '1.5px solid',
              borderColor: form.weekStartsOn === day ? 'var(--accent)' : 'var(--border)',
              backgroundColor: form.weekStartsOn === day ? 'var(--accent)' : 'transparent',
              color: form.weekStartsOn === day ? 'var(--white)' : 'var(--text-secondary)',
              fontFamily: 'Jost, sans-serif', fontSize: '13px', cursor: 'pointer',
            }}>{day}</button>
          ))}
        </div>
      </div>

      {/* Nutrition goals */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '16px' }}>
        <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '14px' }}>DAILY NUTRITION GOALS</p>
        {[
          { key: 'calorieGoal', label: 'CALORIES', unit: 'kcal' },
          { key: 'proteinGoal', label: 'PROTEIN', unit: 'g' },
          { key: 'carbsGoal', label: 'CARBOHYDRATES', unit: 'g' },
          { key: 'fatGoal', label: 'FAT', unit: 'g' },
          { key: 'fiberGoal', label: 'FIBER', unit: 'g' },
          { key: 'sugarGoal', label: 'SUGAR', unit: 'g' },
          { key: 'saltGoal', label: 'SALT', unit: 'g' },
        ].map(item => (
          <div key={item.key} style={{ marginBottom: '14px' }}>
            <label style={labelStyle}>{item.label} ({item.unit})</label>
            <input
              type="number"
              value={form[item.key] === 0 ? '' : form[item.key]}
              onChange={e => setForm({ ...form, [item.key]: e.target.value === '' ? 0 : parseFloat(e.target.value) || 0 })}
              style={inputStyle}
            />
          </div>
        ))}
      </div>

      {/* Fitness goals */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '16px' }}>
        <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '14px' }}>FITNESS GOALS</p>
        <label style={labelStyle}>WEEKLY WORKOUT SESSIONS</label>
        <div style={{ display: 'flex', gap: '8px', marginBottom: '4px' }}>
          {[1, 2, 3, 4, 5, 6, 7].map(n => (
            <button key={n} onClick={() => setForm({ ...form, workoutGoal: n })} style={{
              flex: 1, padding: '10px', borderRadius: '10px', border: '1.5px solid',
              borderColor: form.workoutGoal === n ? 'var(--accent)' : 'var(--border)',
              backgroundColor: form.workoutGoal === n ? 'var(--accent)' : 'transparent',
              color: form.workoutGoal === n ? 'var(--white)' : 'var(--text-secondary)',
              fontFamily: 'Jost, sans-serif', fontSize: '13px', cursor: 'pointer',
            }}>{n}</button>
          ))}
        </div>
      </div>

      {/* Finance */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '16px' }}>
        <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '14px' }}>FINANCE</p>
        <label style={labelStyle}>DEFAULT CURRENCY</label>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {CURRENCIES.map(c => (
            <button key={c} onClick={() => setForm({ ...form, currency: c })} style={{
              padding: '8px 14px', borderRadius: '20px', border: '1px solid',
              borderColor: form.currency === c ? 'var(--accent)' : 'var(--border)',
              backgroundColor: form.currency === c ? 'var(--accent)' : 'transparent',
              color: form.currency === c ? 'var(--white)' : 'var(--text-secondary)',
              fontFamily: 'Jost, sans-serif', fontSize: '13px', cursor: 'pointer',
            }}>{c}</button>
          ))}
        </div>
      </div>

      {/* Integrations */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '16px' }}>
        <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '14px' }}>INTEGRATIONS</p>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <div>
            <p style={{ fontSize: '14px', fontWeight: '500' }}>iPhone Calendar</p>
            <p style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>Sync events with Apple Calendar</p>
          </div>
          <span style={{ fontSize: '11px', padding: '4px 10px', borderRadius: '10px', backgroundColor: 'var(--surface)', color: 'var(--text-secondary)' }}>Coming soon</span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <div>
            <p style={{ fontSize: '14px', fontWeight: '500' }}>Google Calendar</p>
            <p style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>Sync events with Google Calendar</p>
          </div>
          <span style={{ fontSize: '11px', padding: '4px 10px', borderRadius: '10px', backgroundColor: 'var(--surface)', color: 'var(--text-secondary)' }}>Coming soon</span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <p style={{ fontSize: '14px', fontWeight: '500' }}>Notifications</p>
            <p style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>Push notifications for tasks and events</p>
          </div>
          <span style={{ fontSize: '11px', padding: '4px 10px', borderRadius: '10px', backgroundColor: 'var(--surface)', color: 'var(--text-secondary)' }}>Coming soon</span>
        </div>
      </div>

      {/* Data management */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '24px' }}>
        <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '14px' }}>DATA</p>
        <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginBottom: '12px' }}>Your data is synced to Google Sheets automatically.</p>
        <button onClick={() => setShowClearConfirm(true)} style={{
          width: '100%', padding: '12px', borderRadius: '12px',
          border: '1px solid var(--danger)', backgroundColor: 'transparent',
          color: 'var(--danger)', fontFamily: 'Jost, sans-serif',
          fontSize: '14px', cursor: 'pointer',
        }}>Clear all local data</button>
      </div>

      {/* Save button */}
      <button onClick={saveSettings} style={{
        width: '100%', padding: '16px', borderRadius: '14px', border: 'none',
        backgroundColor: saved ? '#7A9E87' : 'var(--accent)', color: 'var(--white)',
        fontFamily: 'Jost, sans-serif', fontSize: '15px', fontWeight: '500',
        cursor: 'pointer', transition: 'background-color 0.3s',
      }}>{saved ? 'Saved ✓' : 'Save Settings'}</button>

      {/* Clear confirm */}
      {showClearConfirm && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Clear all data?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '16px' }}>This will clear local data. Your Google Sheets data will remain intact.</p>
            <p style={{ fontSize: '13px', color: 'var(--danger)', marginBottom: '24px', fontWeight: '500' }}>Type DELETE to confirm:</p>
            <div style={{ display: 'flex', gap: '12px' }}>
            <button onClick={() => { setShowClearConfirm(false); setClearConfirmText(''); }} style={cancelBtnStyle}>Cancel</button>
              <input
                value={clearConfirmText}
                onChange={e => setClearConfirmText(e.target.value)}
                placeholder="Type DELETE"
                style={{ width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--bg)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', marginBottom: '16px', outline: 'none' }}
              />
              <button onClick={clearAllData} disabled={clearConfirmText !== 'DELETE'} style={{ ...deleteBtnStyle, opacity: clearConfirmText !== 'DELETE' ? 0.4 : 1 }}>Clear</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '8px', fontWeight: '500' };
const inputStyle = { width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--bg)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', marginBottom: '4px', outline: 'none' };
const cancelBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const deleteBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--danger)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };

export default Settings;