import React, { useState } from 'react';
import RecipeLibrary from './meals/RecipeLibrary';
import WeeklyPlanner from './meals/WeeklyPlanner';
import ShoppingList from './meals/ShoppingList';
import NutritionOverview from './meals/NutritionOverview';

const TABS = [
  { id: 'recipes', label: 'Recipes' },
  { id: 'planner', label: 'Planner' },
  { id: 'shopping', label: 'Shopping' },
  { id: 'nutrition', label: 'Nutrition' },
];

function Meals({ recipes, setRecipes, planner, setPlanner }) {
    const [activeTab, setActiveTab] = useState('recipes');

  return (
    <div style={{ padding: '32px 24px 24px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em' }}>PLAN</p>
      <h1 style={{ fontSize: '28px', fontWeight: '300', marginTop: '4px', marginBottom: '20px' }}>Meals</h1>

      <div style={{ display: 'flex', gap: '8px', marginBottom: '24px' }}>
        {TABS.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            style={{
              padding: '6px 16px', borderRadius: '20px', border: '1px solid',
              borderColor: activeTab === tab.id ? 'var(--accent)' : 'var(--border)',
              backgroundColor: activeTab === tab.id ? 'var(--accent)' : 'transparent',
              color: activeTab === tab.id ? 'var(--white)' : 'var(--text-secondary)',
              fontSize: '12px', fontFamily: 'Jost, sans-serif', cursor: 'pointer',
            }}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'recipes' && (
        <RecipeLibrary recipes={recipes} setRecipes={setRecipes} />
      )}
      {activeTab === 'planner' && (
        <WeeklyPlanner recipes={recipes} planner={planner} setPlanner={setPlanner} />
      )}
      {activeTab === 'shopping' && (
        <ShoppingList recipes={recipes} planner={planner} />
      )}
      {activeTab === 'nutrition' && (
        <NutritionOverview planner={planner} />
      )}
    </div>
  );
}

export default Meals;