import React, { useState } from 'react';

const CATEGORIES = {
  income: ['Salary', 'Freelance income'],
  expense: ['Food & Groceries', 'Transport', 'Housing & Bills', 'Health', 'Clothing', 'Entertainment', 'Subscriptions', 'Savings'],
};

const ALL_CATEGORIES = [...CATEGORIES.income, ...CATEGORIES.expense];

const CAT_ICONS = {
  'Salary': '💼', 'Freelance income': '💻', 'Food & Groceries': '🛒',
  'Transport': '🚌', 'Housing & Bills': '🏠', 'Health': '🌿',
  'Clothing': '👗', 'Entertainment': '🎬', 'Subscriptions': '📱', 'Savings': '🏦',
};

const emptyForm = {
  title: '', amount: '', type: 'expense',
  category: 'Food & Groceries', date: new Date().toISOString().split('T')[0],
  notes: '', recurring: false,
};

function fmt(amount) {
  return new Intl.NumberFormat('da-DK', { style: 'currency', currency: 'DKK', maximumFractionDigits: 0 }).format(amount);
}

function getMonthName(offset = 0) {
  const d = new Date();
  d.setMonth(d.getMonth() + offset);
  return d.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
}

function getMonthRange(offset = 0) {
  const d = new Date();
  const start = new Date(d.getFullYear(), d.getMonth() + offset, 1);
  const end = new Date(d.getFullYear(), d.getMonth() + offset + 1, 0);
  return { start: start.toISOString().split('T')[0], end: end.toISOString().split('T')[0] };
}

function Finance({ transactions, setTransactions, budgets, setBudgets, savings, setSavings }) {
  const [monthOffset, setMonthOffset] = useState(0);
  const [activeTab, setActiveTab] = useState('overview');
  const [showModal, setShowModal] = useState(false);
  const [showBudgetModal, setShowBudgetModal] = useState(false);
  const [showSavingsModal, setShowSavingsModal] = useState(false);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);
  const [budgetForm, setBudgetForm] = useState({ category: 'Food & Groceries', amount: '' });
  const [savingsForm, setSavingsForm] = useState({ title: '', goal: '', current: '', color: '#7A9E87' });

  const { start, end } = getMonthRange(monthOffset);
  const monthTx = transactions.filter(t => t.date >= start && t.date <= end);
  const totalIncome = monthTx.filter(t => t.type === 'income').reduce((s, t) => s + t.amount, 0);
  const totalExpense = monthTx.filter(t => t.type === 'expense').reduce((s, t) => s + t.amount, 0);
  const balance = totalIncome - totalExpense;

  const expenseByCategory = CATEGORIES.expense.reduce((acc, cat) => {
    acc[cat] = monthTx.filter(t => t.category === cat).reduce((s, t) => s + t.amount, 0);
    return acc;
  }, {});

  function openCreate() { setForm(emptyForm); setEditingId(null); setShowModal(true); }
  function openEdit(tx) {
    setForm({ title: tx.title, amount: tx.amount.toString(), type: tx.type, category: tx.category, date: tx.date, notes: tx.notes || '', recurring: tx.recurring || false });
    setEditingId(tx.id); setShowModal(true);
  }

  function saveTx() {
    if (!form.title.trim() || !form.amount) return;
    const tx = { ...form, amount: parseFloat(form.amount) };
    if (editingId) {
      setTransactions(transactions.map(t => t.id === editingId ? { ...t, ...tx } : t));
    } else {
      setTransactions([...transactions, { ...tx, id: Date.now() }]);
    }
    setShowModal(false);
  }

  function deleteTx(id) { setTransactions(transactions.filter(t => t.id !== id)); setShowDeleteConfirm(null); }

  function saveBudget() {
    if (!budgetForm.amount) return;
    setBudgets({ ...budgets, [budgetForm.category]: parseFloat(budgetForm.amount) });
    setShowBudgetModal(false);
  }

  function saveSavingsGoal() {
    if (!savingsForm.title || !savingsForm.goal) return;
    setSavings([...savings, { ...savingsForm, id: Date.now(), goal: parseFloat(savingsForm.goal), current: parseFloat(savingsForm.current || 0) }]);
    setShowSavingsModal(false);
    setSavingsForm({ title: '', goal: '', current: '', color: '#7A9E87' });
  }

  const SAVINGS_COLORS = ['#7A9E87', '#A0856C', '#7A8FA6', '#B85C5C', '#9B7AB8'];

  return (
    <div style={{ padding: '32px 24px 24px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>

      {/* Header */}
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em' }}>OVERVIEW</p>
      <h1 style={{ fontSize: '28px', fontWeight: '300', marginTop: '4px', marginBottom: '20px' }}>Finance</h1>

      {/* Month navigator */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '20px' }}>
        <button onClick={() => setMonthOffset(monthOffset - 1)} style={navBtnStyle}>‹</button>
        <span style={{ fontSize: '14px', fontWeight: '500', color: 'var(--text-primary)' }}>{getMonthName(monthOffset)}</span>
        <button onClick={() => setMonthOffset(monthOffset + 1)} style={navBtnStyle}>›</button>
      </div>

      {/* Summary cards */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px', marginBottom: '24px' }}>
        {[
          { label: 'Income', value: totalIncome, color: '#7A9E87' },
          { label: 'Expenses', value: totalExpense, color: '#B85C5C' },
          { label: 'Balance', value: balance, color: balance >= 0 ? '#7A9E87' : '#B85C5C' },
        ].map(card => (
          <div key={card.label} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '12px', textAlign: 'center' }}>
            <p style={{ fontSize: '10px', color: 'var(--text-secondary)', letterSpacing: '0.08em', marginBottom: '4px' }}>{card.label.toUpperCase()}</p>
            <p style={{ fontSize: '13px', fontWeight: '600', color: card.color }}>{fmt(card.value)}</p>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
        {['overview', 'transactions', 'budget', 'savings'].map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} style={{
            padding: '6px 12px', borderRadius: '20px', border: '1px solid',
            borderColor: activeTab === tab ? 'var(--accent)' : 'var(--border)',
            backgroundColor: activeTab === tab ? 'var(--accent)' : 'transparent',
            color: activeTab === tab ? 'var(--white)' : 'var(--text-secondary)',
            fontSize: '11px', fontFamily: 'Jost, sans-serif', fontWeight: '500',
            letterSpacing: '0.05em', cursor: 'pointer', textTransform: 'uppercase',
          }}>{tab}</button>
        ))}
      </div>

      {/* OVERVIEW TAB */}
      {activeTab === 'overview' && (
        <div>
          <p style={{ fontSize: '13px', fontWeight: '500', marginBottom: '12px', color: 'var(--text-secondary)', letterSpacing: '0.05em' }}>SPENDING BY CATEGORY</p>
          {CATEGORIES.expense.map(cat => {
            const spent = expenseByCategory[cat] || 0;
            const budget = budgets[cat] || 0;
            const pct = budget > 0 ? Math.min(100, (spent / budget) * 100) : 0;
            const overBudget = budget > 0 && spent > budget;
            if (spent === 0 && budget === 0) return null;
            return (
              <div key={cat} style={{ marginBottom: '14px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px' }}>
                  <span style={{ fontSize: '13px' }}>{CAT_ICONS[cat]} {cat}</span>
                  <span style={{ fontSize: '12px', color: overBudget ? 'var(--danger)' : 'var(--text-secondary)' }}>
                    {fmt(spent)}{budget > 0 ? ` / ${fmt(budget)}` : ''}
                  </span>
                </div>
                {budget > 0 && (
                  <div style={{ height: '4px', backgroundColor: 'var(--surface)', borderRadius: '2px' }}>
                    <div style={{ height: '100%', borderRadius: '2px', width: `${pct}%`, backgroundColor: overBudget ? 'var(--danger)' : 'var(--accent)', transition: 'width 0.3s' }} />
                  </div>
                )}
              </div>
            );
          })}
          {Object.keys(expenseByCategory).every(k => expenseByCategory[k] === 0) && (
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', textAlign: 'center', marginTop: '40px' }}>No transactions this month</p>
          )}
        </div>
      )}

      {/* TRANSACTIONS TAB */}
      {activeTab === 'transactions' && (
        <div>
          {monthTx.length === 0 ? (
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', textAlign: 'center', marginTop: '40px' }}>No transactions this month</p>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {[...monthTx].sort((a, b) => b.date.localeCompare(a.date)).map(tx => (
                <div key={tx.id} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px 16px', display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <span style={{ fontSize: '20px' }}>{CAT_ICONS[tx.category]}</span>
                  <div style={{ flex: 1 }} onClick={() => openEdit(tx)}>
                    <p style={{ fontSize: '14px', fontWeight: '500' }}>{tx.title}</p>
                    <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{tx.category} · {tx.date}</p>
                  </div>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: tx.type === 'income' ? '#7A9E87' : 'var(--text-primary)' }}>
                    {tx.type === 'income' ? '+' : '-'}{fmt(tx.amount)}
                  </p>
                  <button onClick={() => setShowDeleteConfirm(tx.id)} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* BUDGET TAB */}
      {activeTab === 'budget' && (
        <div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginBottom: '16px' }}>
            {CATEGORIES.expense.map(cat => {
              const spent = expenseByCategory[cat] || 0;
              const budget = budgets[cat] || 0;
              const pct = budget > 0 ? Math.min(100, (spent / budget) * 100) : 0;
              const overBudget = budget > 0 && spent > budget;
              return (
                <div key={cat} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px 16px' }}
                  onClick={() => { setBudgetForm({ category: cat, amount: budgets[cat] ? budgets[cat].toString() : '' }); setShowBudgetModal(true); }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '6px' }}>
                    <span style={{ fontSize: '13px' }}>{CAT_ICONS[cat]} {cat}</span>
                    <span style={{ fontSize: '12px', color: overBudget ? 'var(--danger)' : 'var(--text-secondary)' }}>
                      {budget > 0 ? `${fmt(spent)} / ${fmt(budget)}` : 'Tap to set budget'}
                    </span>
                  </div>
                  {budget > 0 && (
                    <div style={{ height: '4px', backgroundColor: 'var(--surface)', borderRadius: '2px' }}>
                      <div style={{ height: '100%', borderRadius: '2px', width: `${pct}%`, backgroundColor: overBudget ? 'var(--danger)' : '#7A9E87', transition: 'width 0.3s' }} />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* SAVINGS TAB */}
      {activeTab === 'savings' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          {savings.length === 0 && (
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', textAlign: 'center', marginTop: '40px' }}>No savings goals yet</p>
          )}
          {savings.map(goal => {
            const pct = Math.min(100, (goal.current / goal.goal) * 100);
            return (
              <div key={goal.id} style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '16px', borderLeft: `4px solid ${goal.color}` }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                  <p style={{ fontSize: '15px', fontWeight: '500' }}>{goal.title}</p>
                  <p style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>{Math.round(pct)}%</p>
                </div>
                <div style={{ height: '6px', backgroundColor: 'var(--surface)', borderRadius: '3px', marginBottom: '8px' }}>
                  <div style={{ height: '100%', borderRadius: '3px', width: `${pct}%`, backgroundColor: goal.color, transition: 'width 0.3s' }} />
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>Saved: {fmt(goal.current)}</span>
                  <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>Goal: {fmt(goal.goal)}</span>
                </div>
              </div>
            );
          })}
          <button onClick={() => setShowSavingsModal(true)} style={{
            padding: '14px', borderRadius: '12px', border: '1.5px dashed var(--border)',
            backgroundColor: 'transparent', color: 'var(--text-secondary)',
            fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer', marginTop: '4px',
          }}>+ Add savings goal</button>
        </div>
      )}

      {/* FAB */}
      {(activeTab === 'overview' || activeTab === 'transactions') && (
        <button onClick={openCreate} style={{
          position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
          width: '52px', height: '52px', borderRadius: '50%',
          backgroundColor: 'var(--accent)', color: 'var(--white)',
          fontSize: '26px', border: 'none', cursor: 'pointer',
          boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>+</button>
      )}

      {/* Delete confirm */}
      {showDeleteConfirm && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Delete transaction?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>This cannot be undone.</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowDeleteConfirm(null)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={() => deleteTx(showDeleteConfirm)} style={deleteBtnStyle}>Delete</button>
            </div>
          </div>
        </div>
      )}

      {/* Transaction modal */}
      {showModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>{editingId ? 'Edit Transaction' : 'New Transaction'}</h3>

            {/* Type toggle */}
            <div style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
              {['expense', 'income'].map(t => (
                <button key={t} onClick={() => setForm({ ...form, type: t, category: t === 'income' ? 'Salary' : 'Food & Groceries' })} style={{
                  flex: 1, padding: '10px', borderRadius: '10px', border: '1.5px solid',
                  borderColor: form.type === t ? (t === 'income' ? '#7A9E87' : '#B85C5C') : 'var(--border)',
                  backgroundColor: form.type === t ? (t === 'income' ? '#7A9E8722' : '#B85C5C22') : 'transparent',
                  color: form.type === t ? (t === 'income' ? '#7A9E87' : '#B85C5C') : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '13px', fontWeight: '600', cursor: 'pointer', textTransform: 'uppercase',
                }}>{t}</button>
              ))}
            </div>

            <label style={labelStyle}>TITLE</label>
            <input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="What was this for?" style={inputStyle} />

            <label style={labelStyle}>AMOUNT (DKK)</label>
            <input type="number" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder="0" style={inputStyle} />

            <label style={labelStyle}>CATEGORY</label>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {CATEGORIES[form.type].map(c => (
                <button key={c} onClick={() => setForm({ ...form, category: c })} style={{
                  padding: '6px 12px', borderRadius: '20px', border: '1px solid',
                  borderColor: form.category === c ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: form.category === c ? 'var(--accent)' : 'transparent',
                  color: form.category === c ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
                }}>{c}</button>
              ))}
            </div>

            <label style={labelStyle}>DATE</label>
            <input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} style={inputStyle} />

            <label style={labelStyle}>NOTES</label>
            <input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Optional note" style={inputStyle} />

            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '28px' }}>
              <input type="checkbox" id="recurring" checked={form.recurring} onChange={e => setForm({ ...form, recurring: e.target.checked })} />
              <label htmlFor="recurring" style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>Recurring transaction</label>
            </div>

            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveTx} style={saveBtnStyle}>{editingId ? 'Save Changes' : 'Add Transaction'}</button>
            </div>
          </div>
        </div>
      )}

      {/* Budget modal */}
      {showBudgetModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>Set Budget — {budgetForm.category}</h3>
            <label style={labelStyle}>MONTHLY BUDGET (DKK)</label>
            <input type="number" value={budgetForm.amount} onChange={e => setBudgetForm({ ...budgetForm, amount: e.target.value })} placeholder="0" style={inputStyle} />
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowBudgetModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveBudget} style={saveBtnStyle}>Save Budget</button>
            </div>
          </div>
        </div>
      )}

      {/* Savings modal */}
      {showSavingsModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>New Savings Goal</h3>
            <label style={labelStyle}>GOAL NAME</label>
            <input value={savingsForm.title} onChange={e => setSavingsForm({ ...savingsForm, title: e.target.value })} placeholder="e.g. Holiday, New laptop" style={inputStyle} />
            <label style={labelStyle}>TARGET AMOUNT (DKK)</label>
            <input type="number" value={savingsForm.goal} onChange={e => setSavingsForm({ ...savingsForm, goal: e.target.value })} placeholder="0" style={inputStyle} />
            <label style={labelStyle}>ALREADY SAVED (DKK)</label>
            <input type="number" value={savingsForm.current} onChange={e => setSavingsForm({ ...savingsForm, current: e.target.value })} placeholder="0" style={inputStyle} />
            <label style={labelStyle}>COLOUR</label>
            <div style={{ display: 'flex', gap: '10px', marginBottom: '28px' }}>
              {SAVINGS_COLORS.map(c => (
                <button key={c} onClick={() => setSavingsForm({ ...savingsForm, color: c })} style={{
                  width: '32px', height: '32px', borderRadius: '50%', backgroundColor: c,
                  border: savingsForm.color === c ? '3px solid var(--text-primary)' : '3px solid transparent',
                  cursor: 'pointer', outline: 'none',
                }} />
              ))}
            </div>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowSavingsModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveSavingsGoal} style={saveBtnStyle}>Add Goal</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const navBtnStyle = {
  background: 'none', border: 'none', fontSize: '22px',
  color: 'var(--text-secondary)', cursor: 'pointer', padding: '4px 10px',
};

const labelStyle = {
  display: 'block', fontSize: '11px', letterSpacing: '0.1em',
  color: 'var(--text-secondary)', marginBottom: '8px', fontWeight: '500',
};

const inputStyle = {
  width: '100%', padding: '12px 14px', borderRadius: '10px',
  border: '1px solid var(--border)', backgroundColor: 'var(--white)',
  fontFamily: 'Jost, sans-serif', fontSize: '14px',
  color: 'var(--text-primary)', marginBottom: '20px', outline: 'none',
};

const cancelBtnStyle = {
  flex: 1, padding: '14px', borderRadius: '12px',
  border: '1px solid var(--border)', backgroundColor: 'transparent',
  fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
};

const saveBtnStyle = {
  flex: 1, padding: '14px', borderRadius: '12px', border: 'none',
  backgroundColor: 'var(--accent)', color: 'var(--white)',
  fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
};

const deleteBtnStyle = {
  flex: 1, padding: '14px', borderRadius: '12px', border: 'none',
  backgroundColor: 'var(--danger)', color: 'var(--white)',
  fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
};

export default Finance;