import React, { useState } from 'react';

const WORK_CATEGORIES = ['VUG', 'Freelance', 'Admin', 'Meeting', 'Other'];
const SHIFT_TYPES = ['Morning', 'Afternoon', 'Evening', 'Full day', 'Custom'];

const emptyShift = {
    name: '',
    date: new Date().toISOString().split('T')[0],
    type: 'Afternoon', start: '13:00', end: '21:00',
    location: '', notes: '',
  };

const emptyTask = {
  title: '', category: 'VUG', priority: 'Medium',
  dueDate: '', notes: '', completed: false,
};

const emptyMeeting = {
  title: '', date: new Date().toISOString().split('T')[0],
  time: '', location: '', attendees: '', notes: '',
};

const emptyTimeLog = {
  date: new Date().toISOString().split('T')[0],
  start: '', end: '', category: 'VUG', description: '',
};

const PRIORITIES = ['Low', 'Medium', 'High'];
const priorityColor = { High: '#B85C5C', Medium: '#A0856C', Low: '#7A9E87' };

function calcHours(start, end) {
    if (!start || !end) return 0;
    const [sh, sm] = start.split(':').map(Number);
    const [eh, em] = end.split(':').map(Number);
    const diff = (eh * 60 + em) - (sh * 60 + sm);
    const hours = Math.max(0, diff / 60);
    return Math.round(hours * 100) / 100;
  }

function formatDate(dateStr) {
  if (!dateStr) return '';
  return new Date(dateStr + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
}

function Work({ shifts, setShifts, workTasks, setWorkTasks, meetings, setMeetings }) {
  const [activeTab, setActiveTab] = useState('schedule');
  const [timeLogs, setTimeLogs] = useState([]);
  const [showShiftModal, setShowShiftModal] = useState(false);
  const [showTaskModal, setShowTaskModal] = useState(false);
  const [showMeetingModal, setShowMeetingModal] = useState(false);
  const [showTimeModal, setShowTimeModal] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);
  const [shiftForm, setShiftForm] = useState(emptyShift);
  const [taskForm, setTaskForm] = useState(emptyTask);
  const [meetingForm, setMeetingForm] = useState(emptyMeeting);
  const [timeForm, setTimeForm] = useState(emptyTimeLog);
  const [editingId, setEditingId] = useState(null);
  const [editingType, setEditingType] = useState(null);
  const [isTracking, setIsTracking] = useState(false);
  const [trackStart, setTrackStart] = useState(null);

  const todayStr = new Date().toISOString().split('T')[0];

  // This week's shifts
  const weekShifts = [...shifts].sort((a, b) => a.date.localeCompare(b.date));

  // Total hours this week
  const now = new Date();
  const monday = new Date(now);
  monday.setDate(now.getDate() - ((now.getDay() + 6) % 7));
  const weekStart = monday.toISOString().split('T')[0];
  const weekEnd = new Date(monday);
  weekEnd.setDate(monday.getDate() + 6);
  const weekEndStr = weekEnd.toISOString().split('T')[0];

  const weekHours = shifts
    .filter(s => s.date >= weekStart && s.date <= weekEndStr)
    .reduce((sum, s) => sum + calcHours(s.start, s.end), 0);

    const monthPrefix = todayStr.slice(0, 7);
    const monthHours = [
      ...shifts.filter(s => s.date.startsWith(monthPrefix)),
      ...timeLogs.filter(t => t.date.startsWith(monthPrefix)),
    ].reduce((sum, s) => sum + calcHours(s.start, s.end), 0);

  function saveShift() {
    if (!shiftForm.date) return;
    if (editingId && editingType === 'shift') {
      setShifts(shifts.map(s => s.id === editingId ? { ...s, ...shiftForm } : s));
    } else {
      setShifts([...shifts, { ...shiftForm, id: Date.now() }]);
    }
    setShowShiftModal(false);
    setEditingId(null);
  }

  function saveTask() {
    if (!taskForm.title.trim()) return;
    if (editingId && editingType === 'task') {
      setWorkTasks(workTasks.map(t => t.id === editingId ? { ...t, ...taskForm } : t));
    } else {
      setWorkTasks([...workTasks, { ...taskForm, id: Date.now() }]);
    }
    setShowTaskModal(false);
    setEditingId(null);
  }

  function saveMeeting() {
    if (!meetingForm.title.trim()) return;
    if (editingId && editingType === 'meeting') {
      setMeetings(meetings.map(m => m.id === editingId ? { ...m, ...meetingForm } : m));
    } else {
      setMeetings([...meetings, { ...meetingForm, id: Date.now() }]);
    }
    setShowMeetingModal(false);
    setEditingId(null);
  }

  function saveTimeLog() {
    if (!timeForm.start || !timeForm.end) return;
    setTimeLogs([...timeLogs, { ...timeForm, id: Date.now() }]);
    setShowTimeModal(false);
  }

  function toggleTask(id) {
    setWorkTasks(workTasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  }

  function deleteItem(type, id) {
    if (type === 'shift') setShifts(shifts.filter(s => s.id !== id));
    if (type === 'task') setWorkTasks(workTasks.filter(t => t.id !== id));
    if (type === 'meeting') setMeetings(meetings.filter(m => m.id !== id));
    if (type === 'time') setTimeLogs(timeLogs.filter(t => t.id !== id));
    setShowDeleteConfirm(null);
  }

  function startTracking() {
    setIsTracking(true);
    setTrackStart(new Date());
  }

  function stopTracking() {
    if (!trackStart) return;
    const end = new Date();
    const startStr = trackStart.toTimeString().slice(0, 5);
    const endStr = end.toTimeString().slice(0, 5);
    setTimeLogs([...timeLogs, {
      id: Date.now(), date: todayStr,
      start: startStr, end: endStr,
      category: 'VUG', description: 'Live session',
    }]);
    setIsTracking(false);
    setTrackStart(null);
  }

  function getLiveTime() {
    if (!trackStart) return '00:00';
    const diff = Math.floor((new Date() - trackStart) / 1000);
    const h = Math.floor(diff / 3600).toString().padStart(2, '0');
    const m = Math.floor((diff % 3600) / 60).toString().padStart(2, '0');
    return `${h}:${m}`;
  }

  const TABS = ['schedule', 'tasks', 'meetings', 'time'];

  return (
    <div style={{ padding: '32px 24px 24px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em' }}>MANAGE</p>
      <h1 style={{ fontSize: '28px', fontWeight: '300', marginTop: '4px', marginBottom: '20px' }}>Work</h1>

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginBottom: '20px' }}>
        {[
          { label: 'Hours this week', value: `${weekHours}h` },
          { label: 'Hours this month', value: `${Math.round(monthHours * 10) / 10}h` },
        ].map(s => (
          <div key={s.label} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px', textAlign: 'center' }}>
            <p style={{ fontSize: '22px', fontWeight: '300', color: 'var(--accent)' }}>{s.value}</p>
            <p style={{ fontSize: '10px', color: 'var(--text-secondary)', letterSpacing: '0.05em' }}>{s.label.toUpperCase()}</p>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '24px', overflowX: 'auto' }}>
        {TABS.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} style={{
            flexShrink: 0, padding: '6px 14px', borderRadius: '20px', border: '1px solid',
            borderColor: activeTab === tab ? 'var(--accent)' : 'var(--border)',
            backgroundColor: activeTab === tab ? 'var(--accent)' : 'transparent',
            color: activeTab === tab ? 'var(--white)' : 'var(--text-secondary)',
            fontSize: '12px', fontFamily: 'Jost, sans-serif', fontWeight: '500',
            letterSpacing: '0.05em', cursor: 'pointer', textTransform: 'uppercase',
          }}>{tab}</button>
        ))}
      </div>

      {/* SCHEDULE TAB */}
      {activeTab === 'schedule' && (
        <div>
          {weekShifts.length === 0 ? (
            <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--text-secondary)' }}>
              <p style={{ fontSize: '32px', marginBottom: '12px' }}>⊞</p>
              <p style={{ fontSize: '14px' }}>No shifts added yet</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {weekShifts.map(shift => (
                <div key={shift.id} style={{
                  backgroundColor: 'var(--white)', borderRadius: '14px', padding: '14px 16px',
                  borderLeft: shift.date === todayStr ? '4px solid var(--accent)' : '4px solid var(--border)',
                }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <div style={{ flex: 1 }} onClick={() => { setShiftForm({ date: shift.date, type: shift.type, start: shift.start, end: shift.end, location: shift.location || '', notes: shift.notes || '' }); setEditingId(shift.id); setEditingType('shift'); setShowShiftModal(true); }}>
                    <p style={{ fontSize: '14px', fontWeight: '500', marginBottom: '2px' }}>{shift.name ? `${shift.name} · ` : ''}{formatDate(shift.date)} {shift.date === todayStr ? '· Today' : ''}</p>
                      <p style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>{shift.start} – {shift.end} · {calcHours(shift.start, shift.end)}h · {shift.type}</p>
                      {shift.location && <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginTop: '2px' }}>{shift.location}</p>}
                    </div>
                    <button onClick={() => setShowDeleteConfirm({ type: 'shift', id: shift.id })} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                  </div>
                </div>
              ))}
            </div>
          )}
          <button onClick={() => { setShiftForm(emptyShift); setEditingId(null); setShowShiftModal(true); }} style={{
            position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
            width: '52px', height: '52px', borderRadius: '50%',
            backgroundColor: 'var(--accent)', color: 'var(--white)', fontSize: '26px',
            border: 'none', cursor: 'pointer', boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>+</button>
        </div>
      )}

      {/* TASKS TAB */}
      {activeTab === 'tasks' && (
        <div>
          {workTasks.length === 0 ? (
            <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--text-secondary)' }}>
              <p style={{ fontSize: '32px', marginBottom: '12px' }}>✓</p>
              <p style={{ fontSize: '14px' }}>No work tasks yet</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {workTasks.map(task => (
                <div key={task.id} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px 16px', display: 'flex', alignItems: 'flex-start', gap: '12px', opacity: task.completed ? 0.5 : 1 }}>
                  <button onClick={() => toggleTask(task.id)} style={{
                    width: '22px', height: '22px', borderRadius: '50%', border: '1.5px solid',
                    borderColor: task.completed ? 'var(--accent)' : 'var(--border)',
                    backgroundColor: task.completed ? 'var(--accent)' : 'transparent',
                    cursor: 'pointer', flexShrink: 0, display: 'flex', alignItems: 'center',
                    justifyContent: 'center', color: 'var(--white)', fontSize: '12px',
                  }}>{task.completed ? '✓' : ''}</button>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontSize: '14px', fontWeight: '500', textDecoration: task.completed ? 'line-through' : 'none', marginBottom: '4px' }}>{task.title}</p>
                    <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                      {task.dueDate && <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>📅 {formatDate(task.dueDate)}</span>}
                      <span style={{ fontSize: '10px', padding: '2px 8px', borderRadius: '10px', backgroundColor: priorityColor[task.priority] + '22', color: priorityColor[task.priority], fontWeight: '600' }}>{task.priority}</span>
                      <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{task.category}</span>
                    </div>
                  </div>
                  <button onClick={() => setShowDeleteConfirm({ type: 'task', id: task.id })} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                </div>
              ))}
            </div>
          )}
          <button onClick={() => { setTaskForm(emptyTask); setEditingId(null); setShowTaskModal(true); }} style={{
            position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
            width: '52px', height: '52px', borderRadius: '50%',
            backgroundColor: 'var(--accent)', color: 'var(--white)', fontSize: '26px',
            border: 'none', cursor: 'pointer', boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>+</button>
        </div>
      )}

      {/* MEETINGS TAB */}
      {activeTab === 'meetings' && (
        <div>
          {meetings.length === 0 ? (
            <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--text-secondary)' }}>
              <p style={{ fontSize: '32px', marginBottom: '12px' }}>◎</p>
              <p style={{ fontSize: '14px' }}>No meetings logged yet</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {[...meetings].sort((a, b) => b.date.localeCompare(a.date)).map(meeting => (
                <div key={meeting.id} style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '14px 16px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontSize: '14px', fontWeight: '500', marginBottom: '4px' }}>{meeting.title}</p>
                      <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '4px' }}>
                        {formatDate(meeting.date)}{meeting.time ? ` · ${meeting.time}` : ''}{meeting.location ? ` · ${meeting.location}` : ''}
                      </p>
                      {meeting.attendees && <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '4px' }}>With: {meeting.attendees}</p>}
                      {meeting.notes && <p style={{ fontSize: '13px', color: 'var(--text-primary)', lineHeight: '1.5', marginTop: '8px', padding: '8px', backgroundColor: 'var(--surface)', borderRadius: '8px' }}>{meeting.notes}</p>}
                    </div>
                    <button onClick={() => setShowDeleteConfirm({ type: 'meeting', id: meeting.id })} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                  </div>
                </div>
              ))}
            </div>
          )}
          <button onClick={() => { setMeetingForm(emptyMeeting); setEditingId(null); setShowMeetingModal(true); }} style={{
            position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
            width: '52px', height: '52px', borderRadius: '50%',
            backgroundColor: 'var(--accent)', color: 'var(--white)', fontSize: '26px',
            border: 'none', cursor: 'pointer', boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>+</button>
        </div>
      )}

      {/* TIME TRACKING TAB */}
      {activeTab === 'time' && (
        <div>
          {/* Live tracker */}
          <div style={{ backgroundColor: isTracking ? 'var(--accent)' : 'var(--white)', borderRadius: '16px', padding: '20px', marginBottom: '16px', textAlign: 'center' }}>
            {isTracking ? (
              <>
                <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'rgba(255,255,255,0.7)', marginBottom: '8px' }}>TRACKING</p>
                <p style={{ fontSize: '40px', fontWeight: '300', color: 'var(--white)', fontVariantNumeric: 'tabular-nums', marginBottom: '16px' }}>{getLiveTime()}</p>
                <button onClick={stopTracking} style={{ padding: '10px 28px', borderRadius: '20px', border: 'none', backgroundColor: 'var(--white)', color: 'var(--accent)', fontFamily: 'Jost, sans-serif', fontSize: '14px', fontWeight: '600', cursor: 'pointer' }}>Stop</button>
              </>
            ) : (
              <>
                <p style={{ fontSize: '14px', color: 'var(--text-secondary)', marginBottom: '12px' }}>Track time live</p>
                <button onClick={startTracking} style={{ padding: '10px 28px', borderRadius: '20px', border: 'none', backgroundColor: 'var(--accent)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' }}>Start timer</button>
              </>
            )}
          </div>

          {/* Time logs */}
          {timeLogs.length === 0 ? (
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', textAlign: 'center', marginTop: '20px' }}>No time logged yet</p>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {[...timeLogs].sort((a, b) => b.date.localeCompare(a.date)).map(log => (
                <div key={log.id} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <p style={{ fontSize: '14px', fontWeight: '500', marginBottom: '2px' }}>{log.description || log.category}</p>
                    <p style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{formatDate(log.date)} · {log.start}–{log.end} · {calcHours(log.start, log.end)}h</p>
                  </div>
                  <button onClick={() => setShowDeleteConfirm({ type: 'time', id: log.id })} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                </div>
              ))}
            </div>
          )}

          <button onClick={() => setShowTimeModal(true)} style={{
            position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
            width: '52px', height: '52px', borderRadius: '50%',
            backgroundColor: 'var(--accent)', color: 'var(--white)', fontSize: '26px',
            border: 'none', cursor: 'pointer', boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>+</button>
        </div>
      )}

      {/* Delete confirm */}
      {showDeleteConfirm && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Delete this item?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>This cannot be undone.</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowDeleteConfirm(null)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={() => deleteItem(showDeleteConfirm.type, showDeleteConfirm.id)} style={deleteBtnStyle}>Delete</button>
            </div>
          </div>
        </div>
      )}

      {/* Shift modal */}
      {showShiftModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>{editingId ? 'Edit Shift' : 'New Shift'}</h3>
            <label style={labelStyle}>SHIFT NAME</label>
            <input value={shiftForm.name} onChange={e => setShiftForm({ ...shiftForm, name: e.target.value })} placeholder="e.g. Klub Relax, AB10, AB8" style={inputStyle} />
            <label style={labelStyle}>DATE</label>
            <input type="date" value={shiftForm.date} onChange={e => setShiftForm({ ...shiftForm, date: e.target.value })} style={inputStyle} />
            <label style={labelStyle}>SHIFT TYPE</label>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {SHIFT_TYPES.map(t => (
                <button key={t} onClick={() => setShiftForm({ ...shiftForm, type: t })} style={{
                  padding: '6px 12px', borderRadius: '20px', border: '1px solid',
                  borderColor: shiftForm.type === t ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: shiftForm.type === t ? 'var(--accent)' : 'transparent',
                  color: shiftForm.type === t ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
                }}>{t}</button>
              ))}
            </div>
            <label style={labelStyle}>START</label>
            <input type="time" value={shiftForm.start} onChange={e => setShiftForm({ ...shiftForm, start: e.target.value })} style={inputStyle} />
            <label style={labelStyle}>END</label>
            <input type="time" value={shiftForm.end} onChange={e => setShiftForm({ ...shiftForm, end: e.target.value })} style={inputStyle} />
            {shiftForm.start && shiftForm.end && (
              <p style={{ fontSize: '13px', color: 'var(--accent)', marginBottom: '20px' }}>Duration: {calcHours(shiftForm.start, shiftForm.end)} hours</p>
            )}
            <label style={labelStyle}>LOCATION</label>
            <input value={shiftForm.location} onChange={e => setShiftForm({ ...shiftForm, location: e.target.value })} placeholder="e.g. AB8, ESK7, AB10" style={inputStyle} />
            <label style={labelStyle}>NOTES</label>
            <textarea value={shiftForm.notes} onChange={e => setShiftForm({ ...shiftForm, notes: e.target.value })} placeholder="Optional notes" rows={3} style={{ ...inputStyle, resize: 'none' }} />
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowShiftModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveShift} style={saveBtnStyle}>{editingId ? 'Save Changes' : 'Add Shift'}</button>
            </div>
          </div>
        </div>
      )}

      {/* Task modal */}
      {showTaskModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>New Work Task</h3>
            <label style={labelStyle}>TITLE</label>
            <input value={taskForm.title} onChange={e => setTaskForm({ ...taskForm, title: e.target.value })} placeholder="What needs to be done?" style={inputStyle} />
            <label style={labelStyle}>CATEGORY</label>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {WORK_CATEGORIES.map(c => (
                <button key={c} onClick={() => setTaskForm({ ...taskForm, category: c })} style={{
                  padding: '6px 12px', borderRadius: '20px', border: '1px solid',
                  borderColor: taskForm.category === c ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: taskForm.category === c ? 'var(--accent)' : 'transparent',
                  color: taskForm.category === c ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
                }}>{c}</button>
              ))}
            </div>
            <label style={labelStyle}>PRIORITY</label>
            <div style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
              {PRIORITIES.map(p => (
                <button key={p} onClick={() => setTaskForm({ ...taskForm, priority: p })} style={{
                  flex: 1, padding: '10px', borderRadius: '10px', border: '1.5px solid',
                  borderColor: taskForm.priority === p ? priorityColor[p] : 'var(--border)',
                  backgroundColor: taskForm.priority === p ? priorityColor[p] + '22' : 'transparent',
                  color: taskForm.priority === p ? priorityColor[p] : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '12px', fontWeight: '600', cursor: 'pointer',
                }}>{p}</button>
              ))}
            </div>
            <label style={labelStyle}>DUE DATE</label>
            <input type="date" value={taskForm.dueDate} onChange={e => setTaskForm({ ...taskForm, dueDate: e.target.value })} style={inputStyle} />
            <label style={labelStyle}>NOTES</label>
            <textarea value={taskForm.notes} onChange={e => setTaskForm({ ...taskForm, notes: e.target.value })} placeholder="Optional notes" rows={3} style={{ ...inputStyle, resize: 'none' }} />
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowTaskModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveTask} style={saveBtnStyle}>Add Task</button>
            </div>
          </div>
        </div>
      )}

      {/* Meeting modal */}
      {showMeetingModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>Log Meeting</h3>
            <label style={labelStyle}>TITLE</label>
            <input value={meetingForm.title} onChange={e => setMeetingForm({ ...meetingForm, title: e.target.value })} placeholder="e.g. MED møde, Personalemøde" style={inputStyle} />
            <label style={labelStyle}>DATE</label>
            <input type="date" value={meetingForm.date} onChange={e => setMeetingForm({ ...meetingForm, date: e.target.value })} style={inputStyle} />
            <label style={labelStyle}>TIME</label>
            <input type="time" value={meetingForm.time} onChange={e => setMeetingForm({ ...meetingForm, time: e.target.value })} style={inputStyle} />
            <label style={labelStyle}>LOCATION</label>
            <input value={meetingForm.location} onChange={e => setMeetingForm({ ...meetingForm, location: e.target.value })} placeholder="e.g. AB8, Online" style={inputStyle} />
            <label style={labelStyle}>ATTENDEES</label>
            <input value={meetingForm.attendees} onChange={e => setMeetingForm({ ...meetingForm, attendees: e.target.value })} placeholder="e.g. Per, Meryam, Mikkel" style={inputStyle} />
            <label style={labelStyle}>NOTES</label>
            <textarea value={meetingForm.notes} onChange={e => setMeetingForm({ ...meetingForm, notes: e.target.value })} placeholder="Meeting notes, decisions, action points..." rows={5} style={{ ...inputStyle, resize: 'none' }} />
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowMeetingModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveMeeting} style={saveBtnStyle}>Save Meeting</button>
            </div>
          </div>
        </div>
      )}

      {/* Time log modal */}
      {showTimeModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>Log Time</h3>
            <label style={labelStyle}>DATE</label>
            <input type="date" value={timeForm.date} onChange={e => setTimeForm({ ...timeForm, date: e.target.value })} style={inputStyle} />
            <div style={{ display: 'flex', gap: '12px', marginBottom: '20px' }}>
              <div style={{ flex: 1 }}>
                <label style={labelStyle}>START</label>
                <input type="time" value={timeForm.start} onChange={e => setTimeForm({ ...timeForm, start: e.target.value })} style={{ ...inputStyle, marginBottom: 0 }} />
              </div>
              <div style={{ flex: 1 }}>
                <label style={labelStyle}>END</label>
                <input type="time" value={timeForm.end} onChange={e => setTimeForm({ ...timeForm, end: e.target.value })} style={{ ...inputStyle, marginBottom: 0 }} />
              </div>
            </div>
            <label style={labelStyle}>CATEGORY</label>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {WORK_CATEGORIES.map(c => (
                <button key={c} onClick={() => setTimeForm({ ...timeForm, category: c })} style={{
                  padding: '6px 12px', borderRadius: '20px', border: '1px solid',
                  borderColor: timeForm.category === c ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: timeForm.category === c ? 'var(--accent)' : 'transparent',
                  color: timeForm.category === c ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
                }}>{c}</button>
              ))}
            </div>
            <label style={labelStyle}>DESCRIPTION</label>
            <input value={timeForm.description} onChange={e => setTimeForm({ ...timeForm, description: e.target.value })} placeholder="What did you work on?" style={inputStyle} />
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowTimeModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveTimeLog} style={saveBtnStyle}>Log Time</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '8px', fontWeight: '500' };
const inputStyle = { width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', marginBottom: '20px', outline: 'none' };
const cancelBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const saveBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--accent)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const deleteBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--danger)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };

export default Work;