import React, { useEffect, useRef, useState } from 'react';
import { BrowserMultiFormatReader } from '@zxing/library';

function BarcodeScanner({ onResult, onClose }) {
  const videoRef = useRef(null);
  const readerRef = useRef(null);
  const [error, setError] = useState(null);
  const [scanning, setScanning] = useState(true);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const reader = new BrowserMultiFormatReader();
    readerRef.current = reader;

    reader.decodeFromVideoDevice(null, videoRef.current, async (result, err) => {
      if (result && scanning) {
        setScanning(false);
        setLoading(true);
        const barcode = result.getText();
        try {
          const res = await fetch(`https://world.openfoodfacts.org/api/v0/product/${barcode}.json`);
          const data = await res.json();
          if (data.status === 1) {
            const p = data.product;
            const n = p.nutriments || {};
            onResult({
              name: p.product_name || p.product_name_en || 'Unknown product',
              barcode,
              per100g: {
                calories: Math.round(n['energy-kcal_100g'] || n['energy_100g'] / 4.184 || 0),
                protein: Math.round((n['proteins_100g'] || 0) * 10) / 10,
                carbs: Math.round((n['carbohydrates_100g'] || 0) * 10) / 10,
                fat: Math.round((n['fat_100g'] || 0) * 10) / 10,
                fiber: Math.round((n['fiber_100g'] || 0) * 10) / 10,
                sugar: Math.round((n['sugars_100g'] || 0) * 10) / 10,
                salt: Math.round((n['salt_100g'] || 0) * 10) / 10,
              },
            });
          } else {
            setError('Product not found on OpenFoodFacts. Try entering manually.');
            setScanning(true);
          }
        } catch (e) {
          setError('Could not fetch product data. Check your connection.');
          setScanning(true);
        }
        setLoading(false);
      }
    });

    return () => { reader.reset(); };
  }, []);

  return (
    <div style={{ position: 'fixed', inset: 0, backgroundColor: '#000', zIndex: 300, display: 'flex', flexDirection: 'column' }}>
      {/* Header */}
      <div style={{ padding: '20px 24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <p style={{ color: '#fff', fontSize: '16px', fontWeight: '500' }}>Scan Barcode</p>
        <button onClick={onClose} style={{ background: 'none', border: 'none', color: '#fff', fontSize: '24px', cursor: 'pointer' }}>✕</button>
      </div>

      {/* Camera */}
      <div style={{ flex: 1, position: 'relative', overflow: 'hidden' }}>
        <video ref={videoRef} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        {/* Scanning frame */}
        <div style={{
          position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <div style={{
            width: '260px', height: '160px', border: '2px solid rgba(255,255,255,0.8)',
            borderRadius: '12px', boxShadow: '0 0 0 9999px rgba(0,0,0,0.5)',
          }} />
        </div>
      </div>

      {/* Status */}
      <div style={{ padding: '24px', textAlign: 'center' }}>
        {loading && <p style={{ color: '#fff', fontSize: '14px' }}>Looking up product...</p>}
        {error && <p style={{ color: '#ffaaaa', fontSize: '13px' }}>{error}</p>}
        {!loading && !error && <p style={{ color: 'rgba(255,255,255,0.6)', fontSize: '13px' }}>Point your camera at a barcode</p>}
      </div>
    </div>
  );
}

export default BarcodeScanner;